// Valida e normaliza o payload recebido do agenda-upsert
const body = $input.first().json.body ?? $input.first().json;

const event      = body.event;            // 'created' | 'confirmed' | 'cancelled'
const clientId   = body.client_id;
const apptId     = body.appointment_id;

if (!event || !clientId) {
  throw new Error('Payload inválido: event e client_id são obrigatórios');
}

// Se os dados do paciente já vieram no payload, usa direto
// Caso contrário, serão buscados no próximo node
return [{
  json: {
    event,
    client_id:      clientId,
    appointment_id: apptId ?? null,
    customer_phone: body.customer_phone ?? null,
    customer_name:  body.customer_name  ?? null,
    service_name:   body.service_name   ?? null,
    start_at:       body.start_at       ?? null,
    end_at:         body.end_at         ?? null,
    needs_lookup:   !body.customer_phone || !body.start_at,
  }
}];

// Mescla dados buscados com payload original
const appt = $input.first().json[0] ?? $input.first().json;
const orig = $('Parsear Payload').first().json;

// whatsapp_notify_phone tem prioridade sobre customer_phone
const phone = appt.whatsapp_notify_phone ?? appt.customer_phone ?? orig.customer_phone;

return [{
  json: {
    event:          orig.event,
    client_id:      appt.client_id      ?? orig.client_id,
    appointment_id: appt.id             ?? orig.appointment_id,
    customer_phone: phone,
    customer_name:  appt.customer_name  ?? orig.customer_name,
    service_name:   appt.service_name   ?? orig.service_name,
    start_at:       appt.start_at       ?? orig.start_at,
    end_at:         appt.end_at         ?? orig.end_at,
  }
}];

const apptData = $('Mesclar Dados').first().json ?? $('Parsear Payload').first().json;
const cfgArr   = $input.first().json;
const cfg      = Array.isArray(cfgArr) ? cfgArr[0] : cfgArr;

if (!cfg) throw new Error('Config WhatsApp não encontrada para client_id: ' + apptData.client_id);

// Verifica se o canal está habilitado para este evento
const enabled  = cfg.whatsapp_notify_enabled ?? false;
const eventKey = `whatsapp_notify_on_${apptData.event}`;
const eventOn  = cfg[eventKey] ?? false;

if (!enabled || !eventOn) {
  return [{ json: { skip: true, reason: `${eventKey} desabilitado` } }];
}

if (!apptData.customer_phone) {
  return [{ json: { skip: true, reason: 'customer_phone não disponível' } }];
}

// Formata data/hora em pt-BR
const fmtDate = (iso) => {
  try {
    return new Date(iso).toLocaleDateString('pt-BR', { weekday: 'long', day: '2-digit', month: 'long' });
  } catch { return iso; }
};
const fmtTime = (iso) => {
  try {
    return new Date(iso).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit', timeZone: 'America/Sao_Paulo' });
  } catch { return iso; }
};

// Substitui variáveis de template
const vars = {
  nome:    apptData.customer_name  ?? 'Cliente',
  servico: apptData.service_name   ?? 'Agendamento',
  data:    fmtDate(apptData.start_at),
  hora:    fmtTime(apptData.start_at),
};
const applyVars = (tpl) => tpl.replace(/\{(\w+)\}/g, (_, k) => vars[k] ?? `{${k}}`);

// Templates padrão por evento
const defaults = {
  created:   `✅ Olá, ${vars.nome}! Seu agendamento de *${vars.servico}* foi confirmado para ${vars.data} às ${vars.hora}.`,
  confirmed: `📋 Olá, ${vars.nome}! Seu agendamento de *${vars.servico}* foi atualizado para ${vars.data} às ${vars.hora}.`,
  cancelled: `❌ Olá, ${vars.nome}! Seu agendamento de *${vars.servico}* foi cancelado. Entre em contato para remarcar.`,
};

const msgKey = `whatsapp_msg_${apptData.event}`;
const rawMsg = cfg[msgKey];
const message = rawMsg?.trim() ? applyVars(rawMsg) : defaults[apptData.event] ?? `Notificação de agendamento: ${vars.servico} em ${vars.data} às ${vars.hora}.`;

// Normaliza número — remove tudo que não for dígito, garante +55
let phone = apptData.customer_phone.replace(/\D/g, '');
if (!phone.startsWith('55')) phone = '55' + phone;
phone = '+' + phone;

return [{
  json: {
    skip:          false,
    client_id:     apptData.client_id,
    connection_id: cfg.whatsapp_connection_id ?? null,
    phone,
    message,
    event:         apptData.event,
    client_name:   cfg.establishment_name ?? 'Estabelecimento',
  }
}];

