const result = $input.first().json;
const skip   = result.skip;
if (skip) {
  console.log(`WhatsApp pulado: ${result.reason}`);
} else if (result.messages) {
  console.log(`WhatsApp enviado para: ${$('Montar Mensagem').first().json.phone}`);
} else {
  console.error(`Erro ao enviar WhatsApp:`, JSON.stringify(result));
}
return $input.all();
